/* Лапа за лапой. No analytics, remote AI, accounts, or background notifications. */
'use strict';
(()=>{
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>Array.from(r.querySelectorAll(s));
const KB=window.KB, G=window.PLAY, KEY='lapaza-puppy-v1', SHARED=/githack|githubraw/.test(location.hostname);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={paw:'M8 16c-1 1-1 4 1 4h6c2 0 2-3 1-4l-2-3c-1-1-3-1-4 0z M8 7a2 3 0 1 0 .1 0 M15 6a2 3 0 1 0 .1 0 M4 11a1.5 2 0 1 0 .1 0 M20 11a1.5 2 0 1 0 .1 0',home:'M3 11l9-8 9 8M5 10v11h14V10M9 21v-7h6v7',sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0',moon:'M20 14A9 9 0 0 1 10 3a9 9 0 1 0 10 11',book:'M12 5v16M12 6C8 3 4 3 2 4v15c3-1 7-1 10 2 3-3 7-3 10-2V4c-3-1-7-1-10 2',heart:'M12 21S2 15 2 8c0-5 7-7 10-2 3-5 10-3 10 2 0 7-10 13-10 13',care:'M5 6h14v15H5zM9 6V3h6v3M12 10v7m-3-3.5h6',shield:'M12 2l9 4v6c0 6-9 10-9 10S3 18 3 12V6zM8 12l3 3 5-6',bag:'M4 7h16v14H4zM8 7V4h8v3M8 11v6m8-6v6',search:'M16 16l5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',arrow:'M4 12h16m-6-6 6 6-6 6',back:'M20 12H4m6-6-6 6 6 6',check:'M4 12l5 5L20 6',medal:'M9 15l-2 7 5-3 5 3-2-7M19 8A7 7 0 1 1 5 8a7 7 0 0 1 14 0',game:'M7 8h10c4 0 7 11 3 12-2 1-3-4-5-4H9c-2 0-3 5-5 4C0 19 3 8 7 8zM7 10v5m-2.5-2.5h5M16 11h.1M18 14h.1',bookmark:'M6 3h12v19l-6-4-6 4z',info:'M12 11v6m0-10h.1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',download:'M12 2v13m-5-5 5 5 5-5M4 17v4h16v-4',settings:'M12 3v3m0 12v3M3 12h3m12 0h3M5.5 5.5l2 2m9 9 2 2M5.5 18.5l2-2m9-9 2-2M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0',clock:'M12 6v7l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',bowl:'M2 10h20l-3 10H5zM5 6h14M8 3h8',drop:'M12 2S4 11 4 15a8 8 0 0 0 16 0c0-4-8-13-8-13z',walk:'M5 5c0-3 6-3 6 0s-6 2-6 5c0 4 12 1 12 6 0 3-4 4-4 4M17 16h4',plug:'M7 2v6m10-6v6M4 8h16v3a8 8 0 0 1-16 0zm8 11v3',sock:'M8 2h9v12l-8 8H3v-7l5-4zM8 6h9',chocolate:'M5 3h14v18H5zM12 3v18M5 9h14M5 15h14',door:'M5 22V2h14v20M14 12h.1M2 22h20',phone:'M7 2h10v20H7zM11 18h2',flag:'M5 22V2m0 1c5-4 9 4 15 0v10c-6 4-10-4-15 0',spark:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',close:'M5 5l14 14M5 19L19 5'};
function icon(n,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.paw}"/></svg>`}
const BASE=()=>({version:1,role:'daughter',phase:'prepare',onboard:false,reads:[],favorites:[],games:{scenarios:[],room:[],bag:false,sequence:false,myths:[]},days:{},checks:{},decision:'none',tripMode:'stay',trip:{},passport:{},logs:[],notes:'',momTab:'prepare'});
let storageOK=true;
function sanitize(v){
 const b=BASE();if(!v||typeof v!=='object'||Array.isArray(v)||v.version!==1)throw Error('Неподдерживаемая версия файла.');
 const str=(x,max=1000)=>typeof x==='string'?x.slice(0,max):'';
 b.role=v.role==='mother'?'mother':'daughter';b.phase=v.phase==='home'?'home':'prepare';b.onboard=!!v.onboard;
 b.reads=[...new Set((Array.isArray(v.reads)?v.reads:[]).filter(x=>KB.chapters.some(c=>c.id===x)))];
 b.favorites=[...new Set((Array.isArray(v.favorites)?v.favorites:[]).filter(x=>KB.chapters.some(c=>c.id===x)))];
 for(const k of ['scenarios','room','myths']){const valid=(k==='room'?G.hazards:G[k]).map(x=>x.id);b.games[k]=[...new Set((Array.isArray(v.games?.[k])?v.games[k]:[]).filter(x=>valid.includes(x)))];}
 for(const k of ['bag','sequence'])b.games[k]=v.games?.[k]===true;
 for(const [day,blocks] of Object.entries(v.days||{}).slice(-180))if(/^\d{4}-\d{2}-\d{2}$/.test(day)&&blocks&&typeof blocks==='object'){
  b.days[day]={};for(const [block,tasks] of Object.entries(blocks))if(/^(prepare|home)-(morning|evening)$/.test(block)){
   b.days[day][block]={};for(const [id,status] of Object.entries(tasks||{}))if(/^t[1-4]$/.test(id)&&['done','help','sleep','todo'].includes(status))b.days[day][block][id]=status;
  }
 }
 for(const [id,c]of Object.entries(v.checks||{}))if(/^c\d{1,2}$/.test(id)&&c&&typeof c==='object')b.checks[id]={status:['none','questions','done'].includes(c.status)?c.status:'none',proof:str(c.proof,600)};
 b.decision=['none','wait','go'].includes(v.decision)?v.decision:'none';b.tripMode=v.tripMode==='travel'?'travel':'stay';
 for(const [k,val]of Object.entries(v.trip||{}))if(/^(stay|travel)-[0-2]-[0-9]+$/.test(k))b.trip[k]=val===true;
 for(const k of ['puppy','clinic','phone','backup','backupphone','food','portion','schedule','vetnotes'])b.passport[k]=str(v.passport?.[k],800);
 b.notes=str(v.notes,4000);b.momTab=['prepare','travel','passport','log','settings'].includes(v.momTab)?v.momTab:'prepare';
 for(const x of (Array.isArray(v.logs)?v.logs:[]).slice(0,250))if(x&&['food','medicine','care'].includes(x.kind)&&typeof x.time==='string'&&Number.isFinite(Date.parse(x.time))){
  b.logs.push({id:str(x.id,80),kind:x.kind,time:str(x.time,35),what:str(x.what,800),who:str(x.who,80)});
 }
 return b;
}
let state=BASE();try{const saved=localStorage.getItem(KEY);if(saved)state=sanitize(JSON.parse(saved));}catch(e){storageOK=false;}
let current='home',part='',search='',filter='all',bookmarksOnly=false,toastTimer=null,quiz={index:0,selected:null},myth={index:0,selected:null},bagSelected=new Set(),bagResult=null,order=[2,0,3,1],orderResult=null,lastFocus=null;
function today(){const t=new Date();return `${t.getFullYear()}-${String(t.getMonth()+1).padStart(2,'0')}-${String(t.getDate()).padStart(2,'0')}`;}
function localDatetime(){const t=new Date();return `${today()}T${String(t.getHours()).padStart(2,'0')}:${String(t.getMinutes()).padStart(2,'0')}`;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;toast('Не получилось сохранить в браузере. Сохраните резервную копию.');}}
function toast(text){const box=$('#toast');box.textContent=text;box.classList.add('toast-show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.classList.remove('toast-show'),4200);}
function celebrate(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const d=document.createElement('div');d.className='confetti';for(let i=0;i<18;i++){let n=document.createElement('i');n.style.setProperty('--dx',`${(i-9)*43}px`);n.style.setProperty('--dy',`${160+Math.random()*290}px`);n.style.setProperty('--rot',`${Math.random()*540}deg`);n.style.background=['#d9b36c','#98b28c','#d99870'][i%3];d.append(n);}document.body.append(d);setTimeout(()=>d.remove(),1400);}
function openModal(title,body){lastFocus=document.activeElement;$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;$('#modal').showModal();$('#close-modal').focus();}
function closeModal(){if($('#modal').open)$('#modal').close();if(lastFocus?.isConnected)lastFocus.focus();}
function go(route){if(location.hash.slice(1)===route)render();else location.hash=route;}
function chapter(id){return KB.chapters.find(x=>x.id===id);}
function tag(id){return KB.groups.find(x=>x.id===id);}
function button(text,action,kind='secondary',attrs=''){return `<button class="button ${kind}" data-action="${action}" ${attrs}>${text}</button>`;}
function artFor(id){if(['sleep','arrival','clean'].includes(id))return 'art-sleep.webp';if(['transport','vacation','organize','kit','home'].includes(id))return 'art-carrier.webp';if(['walk','social','growth','body'].includes(id))return 'art-walk.webp';return 'art-play.webp';}
const navs=[['home','home','Главная'],['day','sun','Мой день'],['library','book','База знаний'],['play','game','Играем и учимся'],['badges','medal','Мои открытия'],['mom','care','Для мамы']];
function layout(){
 const title=navs.find(n=>n[0]===current)?.[2]||({article:'База знаний',emergency:'Срочная помощь',sources:'Источники и фотографии',settings:'Настройки',game:'Играем и учимся'}[current]||'Семейный помощник');
 $('#sidebar').innerHTML=`<a href="#home" class="logo"><span class="logo-icon">${icon('paw')}</span><span>Лапа за лапой<small>Вместе со щенком</small></span></a><nav class="side-nav" aria-label="Основная навигация">${navs.map(([id,ico,name])=>`<a href="#${id}" class="${current===id||(id==='library'&&current==='article')||(id==='play'&&current==='game')?'active':''}" ${current===id?'aria-current="page"':''}>${icon(ico)}${name}</a>`).join('')}</nav><div class="side-note"><span class="eyebrow">Маленькими шагами</span><p>Одна тема. Один новый навык. А потом — время вместе.</p></div><a class="side-sos" href="#emergency">${icon('care')}Срочная помощь</a>`;
 $('#topbar').innerHTML=`<span class="top-label">Семейный помощник <span aria-hidden="true"> / </span> ${esc(title)}</span><a href="#home" class="logo mobile-logo"><span class="logo-icon">${icon('paw')}</span><span>Лапа за лапой<small>Вместе со щенком</small></span></a><div class="top-actions"><a class="sos-top" href="#emergency">${icon('care')}Помощь</a><div class="profile" role="group" aria-label="Режим просмотра"><button data-action="role" data-role="daughter" aria-pressed="${state.role==='daughter'}" class="${state.role==='daughter'?'selected':''}">Дочке</button><button data-action="role" data-role="mother" aria-pressed="${state.role==='mother'}" class="${state.role==='mother'?'selected':''}">Маме</button></div></div>`;
 $('#bottom-nav').innerHTML=[['home','home','Главная'],['day','sun','День'],['library','book','Знания'],['play','game','Игры'],['emergency','care','Помощь']].map(([id,ico,name])=>`<a href="#${id}" class="${current===id||(id==='library'&&current==='article')||(id==='play'&&current==='game')?'active ':''}${id==='emergency'?'sos':''}" ${current===id?'aria-current="page"':''}>${icon(ico)}${name}</a>`).join('');
 $('#footer').innerHTML=`<span>По семейному справочнику о той-пуделе · версия 1.0<span class="storage-alert">${!storageOK?' · Сохранение в браузере недоступно':''}</span></span><span><a href="#sources">Источники и фотографии</a> · <a href="#settings">Данные и настройки</a></span>`;
}
const BADGES=[
 {id:'first',name:'Первый шаг',icon:'paw',text:'Прочитать одну тему.',done:()=>state.reads.length>=1},
 {id:'explorer',name:'Любопытный друг',icon:'book',text:'Прочитать пять тем.',done:()=>state.reads.length>=5},
 {id:'room',name:'Хранитель дома',icon:'home',text:'Разобрать шесть опасностей в учебной комнате.',done:()=>state.games.room.length===G.hazards.length},
 {id:'stories',name:'Понимаю щенка',icon:'heart',text:'Разобрать все игровые истории.',done:()=>state.games.scenarios.length===G.scenarios.length},
 {id:'bag',name:'Готовлюсь к дороге',icon:'bag',text:'Собрать учебную сумку.',done:()=>state.games.bag},
 {id:'sequence',name:'Внимательный помощник',icon:'check',text:'Собрать порядок кормления в игре.',done:()=>state.games.sequence},
 {id:'myths',name:'Проверяю догадки',icon:'spark',text:'Разобрать восемь карточек.',done:()=>state.games.myths.length===G.myths.length},
 {id:'reader',name:'Большое знакомство',icon:'medal',text:'Прочитать все 30 тем.',done:()=>state.reads.length===30}
];
function earned(){return BADGES.filter(b=>b.done()).length;}
function award(update){const before=earned();update();save();if(earned()>before){celebrate();toast('Новое открытие в коллекции!');}}
function featured(id){const c=chapter(id);return `<a class="card card-compact card-link" href="#article/${c.id}"><div class="card-thumb"><img src="assets/${artFor(id)}" alt="Иллюстрация той-пуделя" loading="lazy"><span class="card-number">${String(KB.chapters.indexOf(c)+1).padStart(2,'0')}</span></div><h3>${c.short}</h3><span class="small">${c.minutes} мин чтения ${state.reads.includes(c.id)?' · Прочитано':''}</span></a>`;}
function home(){const parent=state.role==='mother',next=KB.chapters.find(c=>!state.reads.includes(c.id))||KB.chapters[0];
 return `<section class="hero"><div class="hero-copy"><span class="eyebrow">Щенок той-пуделя · семейный помощник</span><h1>${parent?'Забота без<br>лишней суеты.':'Большая дружба.<br>Маленькие шаги.'}</h1><p>${parent?'Понятный план, знания под рукой и спокойная организация ухода. Не нужно помнить всё сразу.':'Узнавай своего щенка, пробуй небольшие задания и учись заботиться — вместе с мамой.'}</p><div class="button-row"><a class="button" href="${parent?'#mom':'#article/'+next.id}">${parent?'Открыть план мамы':state.reads.length?'Продолжить знакомство':'Начать знакомство'}${icon('arrow')}</a><a class="button ghost" href="#day">Мой день</a></div></div><div class="hero-image"><img src="assets/art-play.webp" alt="Иллюстрация абрикосового той-пуделя дома" fetchpriority="high"><span class="hero-sticker">${icon('heart')} Бережно. Понятно. Вместе.</span></div></section>
 <section class="stats" aria-label="Прогресс знакомства"><div class="stat-card"><span class="stat-icon">${icon('book')}</span><div><span class="metric">${state.reads.length}<span class="small"> / 30</span></span><div class="small">тем прочитано</div></div></div><a href="#badges" class="stat-card card-link"><span class="stat-icon">${icon('medal')}</span><div><span class="metric">${earned()}<span class="small"> / 8</span></span><div class="small">значков-открытий</div></div></a><div class="stat-card"><span class="stat-icon">${icon('sun')}</span><div><div style="font-size:15px;font-weight:700">Без гонки за баллами</div><div class="small">За пропуски не штрафуем. Учимся в своём темпе.</div></div></div></section>
 <div class="section-head"><h2>${parent?'Четыре главных опоры':'С чего начнём сегодня?'}</h2><a class="text-link" href="#library">Все темы ${icon('arrow')}</a></div><div class="grid four">${(parent?['purchase','clean','routine','vacation']:['home','routine','body','sleep']).map(featured).join('')}</div>
 <div class="section-head"><h2>Попробуй в игре</h2><a class="text-link" href="#play">Все задания ${icon('arrow')}</a></div><div class="grid two">${gameTile('room','home','Комната глазами щенка','Найди то, что нужно убрать или защитить.','6 находок · без таймера')}${gameTile('stories','heart','Как поступить?','Короткие истории из обычной жизни.','12 ситуаций · можно ошибаться')}</div>
 <div class="note"><div class="row">${icon('info')}<div><strong>Приложение помогает, но не заменяет заботу.</strong><br><span class="small">Посмотри список, убери экран и сделай дела. Запись «Нужна помощь» не отправляет сообщение — скажи маме лично.</span></div></div></div>
 <div class="section-head"><h2>Пудели бывают разными</h2><a class="text-link" href="#sources/photos">Фото и авторы ${icon('arrow')}</a></div><div class="photo-grid">${KB.photos.filter(p=>p.new).map(p=>`<figure><button class="zoom" data-zoom="assets/${p.file}" aria-label="Увеличить фото: ${p.title}"><img loading="lazy" src="assets/${p.file}" style="object-position:${p.file==='photo-white.webp'?'73% 50%':p.file==='photo-miley.webp'?'50% 20%':'center'}" alt="${p.title}"></button><figcaption>${p.title} · ${p.author}<br><a href="${p.url}" target="_blank" rel="noopener noreferrer">Источник</a> · <a href="${p.licurl}" target="_blank" rel="noopener noreferrer">${p.license}</a></figcaption></figure>`).join('')}</div><p class="small" style="margin-top:15px">Это настоящие фотографии. По внешности на фото нельзя определить здоровье щенка.</p>`;
}
function bookCard(c){const g=tag(c.group);return `<article class="card book-card"><div class="topline"><span class="book-icon">${icon(g.icon)}</span><button class="bookmark ${state.favorites.includes(c.id)?'on':''}" data-action="favorite" data-id="${c.id}" aria-pressed="${state.favorites.includes(c.id)}" aria-label="${state.favorites.includes(c.id)?'Убрать закладку':'Добавить закладку'}: ${esc(c.short)}">${icon('bookmark')}</button></div><a class="card-link" href="#article/${c.id}"><h3>${esc(c.short)}</h3><p>${esc(c.description)}</p><div class="row space-between"><span class="small">${c.minutes} мин · ${esc(g.name)}</span>${state.reads.includes(c.id)?'<span class="read-tick">✓</span>':''}</div></a></article>`;}
function bookResults(){const words=search.toLowerCase().replaceAll('ё','е').trim().split(/\s+/).filter(Boolean);return KB.chapters.filter(c=>(filter==='all'||c.group===filter)&&(!bookmarksOnly||state.favorites.includes(c.id))&&words.every(w=>(c.title+' '+c.short+' '+c.text).toLowerCase().replaceAll('ё','е').includes(w)));}
function updateResults(){const list=bookResults();$('#book-results').innerHTML=list.length?list.map(bookCard).join(''):'<div class="empty"><h3>Пока ничего не нашлось</h3><p>Попробуй одно слово: «шерсть», «еда», «сон» или «отпуск».</p></div>';$('#result-count').textContent=`Найдено тем: ${list.length}`;}
function library(){return `<span class="eyebrow">30 тем из семейного справочника</span><h1>Знания под рукой</h1><p class="intro-text">Можно идти по порядку или открыть свой вопрос. Все разделы доступны сразу — даже без значков.</p><label class="search-bar">${icon('search')}<span class="screen-reader">Поиск по всей базе знаний</span><input id="search" type="search" value="${esc(search)}" autocomplete="off" aria-label="Поиск по всей базе знаний"><span class="small">Поиск</span></label><div class="chips" aria-label="Категории"><button class="chip ${filter==='all'?'active':''}" data-action="filter" data-filter="all">Все темы</button>${KB.groups.map(g=>`<button class="chip ${filter===g.id?'active':''}" data-action="filter" data-filter="${g.id}">${g.name}</button>`).join('')}</div><div class="row space-between" style="margin-bottom:16px"><span id="result-count" class="small" role="status"></span><button class="chip ${bookmarksOnly?'active':''}" data-action="bookmarks" aria-pressed="${bookmarksOnly}">${icon('bookmark')} Мои закладки</button></div><div class="book-grid" id="book-results"></div>`;}
function article(id){const c=chapter(id);if(!c)return notFound();const n=KB.chapters.indexOf(c);return `<article class="reader"><div class="reader-head"><a class="text-link" href="#library">${icon('back')}К базе знаний</a><h1>${esc(c.title)}</h1><div class="reader-meta"><span class="pill">${esc(tag(c.group).name)}</span><span>${c.minutes} мин чтения · тема ${n+1} из 30</span><button class="bookmark ${state.favorites.includes(c.id)?'on':''}" data-action="favorite" data-id="${c.id}" aria-pressed="${state.favorites.includes(c.id)}" aria-label="Закладка: ${c.short}">${icon('bookmark')}</button></div></div><div class="reader-body">${c.html}</div><div class="card reader-bottom"><div><strong>${state.reads.includes(id)?'Тема отмечена как прочитанная':'Прочитали и обсудили?'}</strong><div class="small">Отметка — про чтение, не про выполненный уход.</div></div><button class="button ${state.reads.includes(id)?'secondary':''}" data-action="read" data-id="${id}">${icon('check')}${state.reads.includes(id)?'Уже прочитано':'Отметить как прочитанное'}</button></div><div class="reader-pagination">${n?`<a class="button secondary" href="#article/${KB.chapters[n-1].id}">${icon('back')}Предыдущая</a>`:'<span></span>'}${n<29?`<a class="button secondary" href="#article/${KB.chapters[n+1].id}">Следующая${icon('arrow')}</a>`:'<a class="button secondary" href="#badges">Мои открытия</a>'}</div><p class="small" style="margin-top:25px">Текст и схема — из исходного DOCX. Порции, препараты и сроки для конкретного щенка назначает ветеринар. <a href="#sources">Источники</a>.</p></article>`;}
const TASKS={prepare:{morning:[['Убрать свои вещи с пола','Одежда, школьные вещи и мелочи на местах.'],['Начать дела по своему напоминанию','Не ждать папиного напоминания.'],['Посмотреть план дня с мамой','Кто будет рядом днём и вечером?']],evening:[['Навести порядок в своей зоне','Готовим безопасное место, а не идеальную квартиру.'],['Выделить время до развлечений','Пробуем будущий вечерний режим без щенка.'],['Обсудить одну маленькую задачу','Например, куда уберём провод или где будет лежанка.']]},home:{morning:[['Посмотреть на щенка и проверить воду','Если что-то необычно — сразу сказать маме.'],['Помочь с назначенными делами','Кормление и туалет — по плану мамы. Сначала проверить, что уже сделано.'],['Спокойно пообщаться и убрать свои вещи','Не будить ради галочки. Время общения можно перенести с мамой.']],evening:[['Спокойная игра или прогулка со взрослым','Без планшета в руках. По состоянию щенка.'],['Маленький навык и бережный уход','Только то, чему научила мама; остановиться при страхе или боли.'],['Порядок и подготовка на завтра','Личные вещи на местах; о загрязнениях и проблемах сообщить маме.']]}};
function dayBlock(block){const key=state.phase+'-'+block,tasks=TASKS[state.phase][block],s=state.days[today()]?.[key]||{},isMorning=block==='morning';return `<section class="card"><img class="day-art" src="assets/art-${isMorning?'play':'sleep'}.webp" alt="Иллюстрация: ${isMorning?'щенок дома':'спящий щенок'}"><div class="row space-between"><h2>${isMorning?'Моё утро':'Мой вечер'}</h2><span class="pill">${isMorning?'около 20':'около 30'} мин</span></div><p class="small">${isMorning?'До первого развлекательного экрана.':'После школы или вечером — как договорились с мамой.'} Это резерв времени, не таймер.</p><div class="tasks">${tasks.map(([title,desc],i)=>{const id='t'+(i+1),v=s[id]||'todo';return `<div class="task ${v}"><div class="task-top"><span class="check-circle">${v==='done'?'✓':v==='help'?'!':v==='sleep'?'↻':''}</span><div><div class="task-title">${title}</div><small>${desc}</small></div></div><div class="task-actions"><button data-action="task" data-block="${block}" data-id="${id}" data-status="done" class="${v==='done'?'is-selected':''}" aria-pressed="${v==='done'}">Сделано</button><button data-action="task" data-block="${block}" data-id="${id}" data-status="help" class="${v==='help'?'help-selected':''}" aria-pressed="${v==='help'}">Нужна помощь</button>${state.phase==='home'&&i===2?`<button data-action="task" data-block="${block}" data-id="${id}" data-status="sleep" class="${v==='sleep'?'is-selected':''}">Часть перенесли</button>`:''}${v!=='todo'?`<button data-action="task" data-block="${block}" data-id="${id}" data-status="todo" aria-label="Отменить отметку: ${title}">Отменить</button>`:''}</div></div>`;}).join('')}</div></section>`;}
function week(){let out='';for(let i=6;i>=0;i--){let d=new Date();d.setDate(d.getDate()-i);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;out+=`<div class="day-cell ${i===0?'today':''}"><div>${d.toLocaleDateString('ru-RU',{weekday:'short'})}</div><strong>${d.getDate()}</strong><div class="day-dots">${['morning','evening'].map(block=>{const v=Object.values(state.days[key]?.[state.phase+'-'+block]||{});let cls=v.includes('help')?'help':v.filter(x=>x==='done').length===3?'done':'';return `<span class="dot ${cls}" aria-label="${block==='morning'?'Утро':'Вечер'}: ${cls==='done'?'все отметки сделаны':cls==='help'?'нужна помощь':'не всё отмечено'}"></span>`;}).join('')}</div></div>`;}return out;}
function day(){return `<div class="day-head"><div><span class="eyebrow">${new Date().toLocaleDateString('ru-RU',{day:'numeric',month:'long',weekday:'long'})}</span><h1>Сначала забота.<br>Потом — отдых.</h1></div><div class="phase-switch" role="group" aria-label="Этап семьи"><button class="chip ${state.phase==='prepare'?'active':''}" data-action="phase" data-phase="prepare">Готовимся к щенку</button><button class="chip ${state.phase==='home'?'active':''}" data-action="phase" data-phase="home">Щенок уже дома</button></div></div><p class="intro-text">Посмотри список, убери экран и сделай дела. Отмечай после. Не нужно держать приложение открытым во время общения со щенком.</p><div class="grid two">${dayBlock('morning')}${dayBlock('evening')}</div><div class="note warn"><strong>Это только часть ухода, которую выполняет дочка.</strong><p>Дневные и ночные потребности обеспечивает мама или согласованный взрослый. Сон, болезнь, еда и необходимая учёба ребёнка не становятся наказанием. Если нужна помощь — скажи маме: приложение никого не уведомляет.</p></div><div class="grid two"><section class="card"><h3>Без долгов и потерянных серий</h3><div class="week-strip">${week()}</div><p class="small">Две точки — утро и вечер. Зелёная: список отмечен. Жёлтая: нужна помощь. Пустая: не всё отмечено. Это самоотметки, не проверка качества ухода.</p></section><section class="card"><h3>Правило пяти зон</h3>${['Безопасные пол и проходы','Чистое туалетное место','Миски и свежая вода','Сухая чистая лежанка','Свои вещи и принадлежности на местах'].map((t,i)=>`<div class="factline"><span class="pill">${i+1}</span><span style="font-size:14px">${t}</span></div>`).join('')}<a class="text-link" href="#article/clean" style="margin-top:16px">Как организовать уборку${icon('arrow')}</a></section></div>`;}
function gameTile(id,ico,title,desc,meta){return `<article class="card game-tile"><div class="game-art">${icon(ico)}</div><div><span class="eyebrow" style="margin-bottom:7px">${meta}</span><h3>${title}</h3><p>${desc}</p><a class="button secondary sm" href="#game/${id}">Попробовать ${icon('arrow')}</a></div></article>`;}
function play(){return `<span class="eyebrow">Небольшие задания · большая польза</span><h1>Сначала попробуем<br>в игре.</h1><p class="intro-text">Здесь можно ошибаться и разбираться. Без таймера и потери баллов. Одного короткого задания на сегодня достаточно.</p><div class="grid two">${gameTile('room','home','Комната глазами щенка','Найди шесть опасностей и узнай, кто поможет их убрать.','Поиск на картинке')}${gameTile('stories','heart','Как поступить?','Сон, гости, лужа на полу и ещё девять обычных ситуаций.','12 коротких историй')}${gameTile('bag','bag','Собери сумку','Что подготовить для дороги и передачи ухода?','Выбор предметов')}${gameTile('sequence','bowl','Порядок кормления','Расставь шаги кнопками вверх и вниз.','Собери последовательность')}${gameTile('myths','spark','Верю — проверяю','Разберись с восемью распространёнными догадками.','Карточки с объяснениями')}${gameTile('badges','medal','Моя коллекция','Посмотри, что уже получилось узнать и попробовать.','8 добрых открытий')}</div><div class="note"><strong>Учебная игра — не выполненный уход.</strong><p>За настоящие кормления, лекарства и прогулки игровые баллы не начисляются. Всё важное для здоровья всегда доступно в разделе помощи.</p></div>`;}
function gameHeader(k,title,subtitle){return `<div class="game-screen"><a class="text-link" href="#play">${icon('back')}К заданиям</a><span class="eyebrow" style="margin-top:25px">Учебное задание · не реальная проверка</span><h1>${title}</h1><p class="intro-text">${subtitle}</p>`;}
function roomSVG(){return `<svg viewBox="0 0 800 500" preserveAspectRatio="none" role="img" aria-label="Учебная комната: провод, шоколад, носок, лекарство, открытый балкон и пластиковый пакет"><rect width="800" height="335" fill="#eee6d7"/><path d="M0 335h800v165H0z" fill="#d3bba1"/><path d="M0 405h800M220 335l-70 165m260-165 30 165m180-165 80 165" stroke="#bea083" stroke-width="2"/><rect x="568" y="35" width="192" height="268" rx="5" fill="#fef9ef"/><rect x="580" y="47" width="170" height="244" fill="#bfd5c8"/><path d="M641 48h110v242H641z" fill="#bfdce2"/><path d="M620 304h150" stroke="#577364" stroke-width="8"/><path d="M579 46l66 14v252l-66-22z" fill="#e1f0e8" stroke="#86a295" stroke-width="3"/><rect x="143" y="111" width="345" height="168" rx="25" fill="#9cb39f"/><rect x="160" y="131" width="145" height="92" rx="14" fill="#b5c7b5"/><rect x="317" y="131" width="151" height="92" rx="14" fill="#b5c7b5"/><rect x="131" y="219" width="367" height="76" rx="18" fill="#89a78f"/><path d="M162 292v28m305-28v28" stroke="#67594b" stroke-width="10"/><path d="M76 166v115c0 21 50 30 40 50s-40-4-18 17" fill="none" stroke="#6d655d" stroke-width="7"/><rect x="53" y="110" width="45" height="70" rx="8" fill="#faf6ee"/><path d="M67 134v11m17-11v11" stroke="#817769" stroke-width="4"/><ellipse cx="261" cy="272" rx="115" ry="34" fill="#f5e6c7"/><path d="M173 278v58m180-58v58" stroke="#997d5e" stroke-width="9"/><g transform="translate(215 235) rotate(-9)"><rect width="58" height="32" rx="3" fill="#705141"/><path d="M20 1v30m19-30v30M1 16h56" stroke="#b28669" stroke-width="2"/></g><g transform="translate(301 422) rotate(21)"><path d="M5 0h25v31l-19 23H-9V33L5 22z" fill="#dee7ef" stroke="#93a8ad" stroke-width="3"/></g><g transform="translate(596 380) rotate(-14)"><rect width="33" height="64" rx="5" fill="#fffdf1" stroke="#a69381" stroke-width="2"/><path d="M0 7h33" stroke="#8b746a" stroke-width="9"/><path d="M8 36h18m-9-9v18" stroke="#bc7971" stroke-width="5"/></g><path d="M454 285h42l12 63-68 0z" fill="#f7f3e7" stroke="#abac9c" stroke-width="3"/><path d="M461 287v-16h29v16" fill="none" stroke="#abac9c" stroke-width="4"/><ellipse cx="133" cy="432" rx="67" ry="30" fill="#7f9a82"/><ellipse cx="133" cy="427" rx="51" ry="19" fill="#b5c7aa"/><ellipse cx="692" cy="335" rx="37" ry="14" fill="#c2d9d8"/><path d="M655 335l8 22h57l9-22" fill="#c2d9d8" stroke="#7da5a3" stroke-width="2"/></svg>`;}
function roomGame(){const n=state.games.room.length;return gameHeader('room','Комната глазами щенка','Нажми на номер рядом с предметом. Прочитай объяснение и отметь, что разобралась. Можно пользоваться списком под картинкой.')+`<div class="game-status"><span>Разобрали ${n} из ${G.hazards.length}</span><a href="#article/home">Памятка о доме</a></div><div class="progress"><span style="width:${n/G.hazards.length*100}%"></span></div><div class="room">${roomSVG()}${G.hazards.map((h,i)=>`<button class="hotspot ${state.games.room.includes(h.id)?'found':''}" style="left:${h.x}%;top:${h.y}%" data-action="hazard" data-id="${h.id}" aria-label="Находка ${i+1}: ${h.name}">${state.games.room.includes(h.id)?'✓':i+1}</button>`).join('')}</div><div class="hazard-list">${G.hazards.map((h,i)=>`<button class="hazard-item ${state.games.room.includes(h.id)?'found':''}" data-action="hazard" data-id="${h.id}"><span>${state.games.room.includes(h.id)?'✓':i+1}</span>${h.name}</button>`).join('')}</div>${n===G.hazards.length?`<div class="feedback"><h3>Шесть находок разобраны!</h3><p>Теперь можно вместе с мамой посмотреть на свою комнату. Эта учебная картинка не подтверждает, что реальный дом безопасен.</p><a class="button secondary" href="#badges">Моя коллекция</a></div>`:''}</div>`;}
function storyGame(){if(quiz.index>=G.scenarios.length)return gameHeader('stories','Истории разобраны','Ты потренировалась замечать, когда помочь самой, когда отступить и когда позвать взрослого.')+`<div class="badge-pop">${icon('heart')}<h2>Сегодня уже достаточно экрана.</h2><p>Можно закрыть приложение и отдохнуть вместе — по состоянию щенка.</p><div class="button-row" style="justify-content:center"><a class="button" href="#badges">Мои открытия</a>${button('Разобрать ещё раз','restart-stories')}</div></div></div>`;const q=G.scenarios[quiz.index],sel=quiz.selected;return gameHeader('stories','Как поступить?','Одна ситуация — одно спокойное решение. Можно остановиться после любой истории.')+`<div class="game-status"><span>История ${quiz.index+1} из ${G.scenarios.length}</span><span>${state.games.scenarios.length} разобрано</span></div><div class="progress"><span style="width:${(quiz.index)/G.scenarios.length*100}%"></span></div><section class="game-panel"><span class="eyebrow">${q.title}</span><h2>${q.scene}</h2><div class="options">${q.options.map((o,i)=>`<button class="option ${sel!==null?(i===q.answer?'correct':i===sel?'incorrect':''):''}" data-action="answer" data-answer="${i}" ${sel!==null?'disabled':''}><span class="letter">${['А','Б','В'][i]}</span><span>${o}</span></button>`).join('')}</div>${sel!==null?`<div class="feedback ${sel!==q.answer?'wrong':''}" role="status"><h3>${sel===q.answer?'Да, бережное решение.':'Давай разберёмся — ошибаться можно.'}</h3><p>${q.why}</p><div class="button-row">${button(quiz.index===G.scenarios.length-1?'Завершить':'Понятно, дальше','next-story','')}<a class="text-link" href="#article/${q.article}">Почему так ${icon('book')}</a></div></div>`:''}</section></div>`;}
function bagGame(){return gameHeader('bag','Собери сумку','Выбери всё, что нужно подготовить для поездки или передачи ухода. Нажатие добавляет предмет, повторное — убирает.')+`<div class="note"><strong>Это учебная сумка.</strong> Реальный маршрут, документы, корм и принимающего взрослого проверяет мама.</div><div class="bag-grid">${G.bag.map(([id,text,ico])=>`<button class="bag-item ${bagSelected.has(id)?'selected':''}" data-action="bag-item" data-id="${id}" aria-pressed="${bagSelected.has(id)}">${icon(ico)}<span>${text}</span></button>`).join('')}</div><div class="button-row">${button('Проверить сумку','check-bag','')}${button('Снять выбор','clear-bag')}</div>${bagResult?`<div class="feedback ${bagResult.ok?'':'wrong'}" role="status"><h3>${bagResult.ok?'Учебная сумка собрана!':'Немного поправим.'}</h3><p>${esc(bagResult.message)}</p><a class="text-link" href="#article/vacation">Открыть памятку мамы ${icon('arrow')}</a></div>`:''}</div>`;}
function sequenceGame(){return gameHeader('sequence','Сначала проверить,<br>потом покормить.','Расположи четыре шага по порядку. Используй стрелки — перетаскивать ничего не нужно.')+`<ol class="order-list">${order.map((id,i)=>`<li><span class="order-num">${i+1}</span><span class="order-text">${G.sequence[id]}</span><div class="order-controls"><button data-action="order" data-index="${i}" data-dir="-1" aria-label="Поднять шаг: ${G.sequence[id]}" ${i===0?'disabled':''}>↑</button><button data-action="order" data-index="${i}" data-dir="1" aria-label="Опустить шаг: ${G.sequence[id]}" ${i===order.length-1?'disabled':''}>↓</button></div></li>`).join('')}</ol>${button('Проверить порядок','check-order','')}${orderResult!==null?`<div class="feedback ${orderResult?'':'wrong'}" role="status"><h3>${orderResult?'Порядок верный.':'Посмотри на первый шаг.'}</h3><p>${orderResult?'Сначала выясняем, что уже сделали. Потом даём согласованную порцию и записываем факт. Эта игра не означает, что щенка сейчас нужно кормить.':'Сначала проверяют план и последнюю запись, затем отмеряют порцию, предлагают еду и записывают результат. Попробуй ещё раз.'}</p><a href="#article/feeding">Памятка о питании</a></div>`:''}</div>`;}
function mythGame(){if(myth.index>=G.myths.length)return gameHeader('myths','Догадки проверены','Восемь карточек разобраны. Не нужно запоминать всё сразу — база всегда под рукой.')+`<div class="badge-pop">${icon('spark')}<h2>Спрашивать и проверять — полезно.</h2><div class="button-row" style="justify-content:center"><a class="button" href="#badges">Мои открытия</a>${button('Пройти ещё раз','restart-myths')}</div></div></div>`;const q=G.myths[myth.index],s=myth.selected;return gameHeader('myths','Верю — проверяю','Как ты думаешь, верно ли утверждение? После ответа появится объяснение.')+`<div class="game-status"><span>Карточка ${myth.index+1} из ${G.myths.length}</span><a href="#play">Закончить на сегодня</a></div><div class="flashcard"><span class="eyebrow">Проверяем догадку</span><h2>${q.text}</h2></div><div class="button-row" style="justify-content:center"><button class="button" data-action="myth-answer" data-value="true" ${s!==null?'disabled':''}>Думаю, верно</button><button class="button secondary" data-action="myth-answer" data-value="false" ${s!==null?'disabled':''}>Думаю, неверно</button></div>${s!==null?`<div class="feedback ${s===q.answer?'':'wrong'}" role="status"><h3>${q.answer?'Это верно.':'Это неверно.'}</h3><p>${q.why}</p><div class="button-row">${button(myth.index===G.myths.length-1?'Завершить':'Следующая карточка','next-myth','')}<a href="#article/${q.article}">Читать в базе</a></div></div>`:''}</div>`;}
function badges(){return `<span class="eyebrow">Не рейтинг, а напоминание о новом</span><h1>Мои открытия</h1><p class="intro-text">Значки остаются с тобой. Здесь нет наказаний за паузы и нет наград за лишнее кормление или лекарства.</p><div class="badges">${BADGES.map(b=>`<article class="badge ${b.done()?'unlocked':''}"><div class="badge-symbol">${icon(b.icon)}</div><h3>${b.name}</h3><p>${b.text}</p><span class="pill ${b.done()?'peach':''}">${b.done()?'Уже в коллекции':'Ещё впереди'}</span></article>`).join('')}</div><div class="note">${earned()===8?'Все восемь открытий уже в коллекции. Но вопросы всегда можно открыть снова.':'Выбирай интересную тему или игру. Одного небольшого шага на сегодня достаточно.'}</div><div class="button-row"><a class="button" href="#play">Выбрать задание</a><a class="button secondary" href="#library">Открыть базу</a></div>`;}
const PREP=[
 ['Мама добровольно согласна на взрослую ответственность','В том числе когда дочка болеет, занята или теряет интерес.'],
 ['Проверены заводчик, условия и документы','Возраст, мать и помёт, документы, сведения о лечении, прививках и обработках.'],
 ['Проверены обследования родителей','prcd-PRA, осмотр глаз, коленные чашечки. Подтверждения обсуждены с ветеринаром.'],
 ['Независимый осмотр до окончательной оплаты','Наше семейное условие: выбранный мамой ветеринар осматривает щенка, вопросы разобраны.'],
 ['Есть план питания и привычный корм','Точный корм, порция и интервалы — для выбранного щенка, с ветеринаром.'],
 ['Есть план прививок, паразитов и первого визита','Даты и препараты не назначаются этим приложением.'],
 ['Подтверждены клиника, экстренная помощь и дорога','Мама знает, куда звонить, как ехать и чем оплачивать помощь.'],
 ['Дом готов, места и безопасные вещи организованы','Проверены пол, провода, мусор, окна, двери, лежанка, миски и переноска.'],
 ['Дневной уход и запасной взрослый реально согласованы','Не «кто-нибудь поможет», а конкретное согласие; подмена есть и для мамы.'],
 ['Бюджет, резерв и ближайший отпуск разобраны','Уход не переходит к папе автоматически. Поездка или передержка подтверждены.']
];
function prepReady(){return PREP.every((_,i)=>state.checks['c'+i]?.status==='done'&&state.checks['c'+i]?.proof?.trim());}
function prepSummary(){const count=PREP.filter((_,i)=>state.checks['c'+i]?.status==='done'&&state.checks['c'+i]?.proof?.trim()).length;
 const text=state.decision==='wait'?'Покупку отложили — даже если отдельные проверки выполнены.':!prepReady()?`Завершено с записью: ${count} из ${PREP.length}. Остальные вопросы ещё нужно разобрать.`:state.decision!=='go'?'Список заполнен. Решение мамы после обсуждения с врачом ещё не принято.':'Семейная проверка завершена. Это не медицинское заключение и не гарантия здоровья.';
 return `<div class="note ${state.decision==='wait'?'warn':''}" role="status"><strong>${text}</strong></div>`;
}
function sharedWarning(){return `<div class="note warn"><strong>Публичная демонстрационная ссылка</strong><p>На общем домене сервиса личные контакты, назначения и записи не сохраняются. Здесь работают знания, игры, отметки чтения и учебные списки. Для личных записей используйте комплект на своём устройстве или отдельный домен. Не вводите здесь фамилии, телефоны и медицинские сведения.</p></div>`;}
function prepView(){return `<p class="small">Результат «Готово» означает, что вопрос разобран и есть запись, а не просто «мы посмотрели». <a href="#article/purchase">Полная памятка до покупки</a>.</p>${SHARED?sharedWarning():''}<div id="prep-summary">${prepSummary()}</div><section class="card">${PREP.map(([name,desc],i)=>{const id='c'+i,c=state.checks[id]||{};return `<div class="check-row"><div><p><strong>${i+1}. ${name}</strong></p><small>${desc}</small></div><label class="field"><span class="screen-reader">Статус: ${name}</span><select data-prep="${id}" class="control"><option value="none" ${!c.status||c.status==='none'?'selected':''}>Не проверили</option><option value="questions" ${c.status==='questions'?'selected':''}>Остались вопросы</option><option value="done" ${c.status==='done'?'selected':''}>Готово</option></select></label>${SHARED?`<label class="checklabel proof"><input type="checkbox" data-proof-tick="${id}" ${c.proof?'checked':''}><span>Мама проверила подтверждение и разобрала вопросы. Оригинал хранится у неё.</span></label>`:`<label class="field proof">Что проверено / какие вопросы остались<input maxlength="600" data-proof="${id}" value="${esc(c.proof||'')}"><span class="small">Для «Готово» нужна запись. Персональные данные в неё включать не обязательно.</span></label>`}</div>`;}).join('')}</section><div class="card" style="margin-top:20px"><label class="field">Решение мамы после обсуждения с ветеринаром<select id="decision"><option value="none" ${state.decision==='none'?'selected':''}>Ещё не принято</option><option value="wait" ${state.decision==='wait'?'selected':''}>Покупку отложили</option><option value="go" ${state.decision==='go'?'selected':''}>Можем переходить к покупке</option></select></label><p class="small" style="margin-top:12px">Приложение не оценивает анализы. Нельзя получить «готовность» одним заполненным комментарием или автоматической формулой.</p></div>`;}
const TRIP={stay:[['Помощник или передержка согласились принять именно этого щенка.','Подходят возраст, здоровье, прививки, кормления, туалет и ночной уход.','Понятны цена, оплата, доставка, получение и запасной вариант.'],['Договорённости повторно подтверждены перед отъездом.','Переданы привычный корм, документы, контакты врача и назначения.','Записано, когда были последние еда, лекарства и туалет.','Помощник ответил, что щенка принял и всё понял.'],['Щенок получен обратно согласованным взрослым.','Выяснили, как прошёл уход, какие еда и лекарства уже даны.','Забрали документы и вещи, обсудили дальнейший режим.']],travel:[['Проверены выезд, въезд, транзит, возвращение и конкретный перевозчик.','Приём животного на нужном рейсе и размещение подтверждены.','С ветеринаром разобраны документы, сроки и допустимость поездки.','Есть подходящая переноска, бюджет и запасной вариант.'],['Требования маршрута и перевозчика повторно проверены.','Подготовлены документы, корм, вода, контакты клиник и назначения.','Уточнены последние еда и лекарства, организована безопасная дорога.'],['Выяснили самочувствие щенка и что уже сделано в дороге.','Вернулись к согласованному режиму, документы и вещи сохранены.']]};
function tripView(){const mode=state.tripMode;return `<p class="small">Мама организует весь путь: договорённость, оплату, дорогу, передачу и возвращение. <a href="#article/vacation">Полная памятка</a>.</p><div class="chips"><button class="chip ${mode==='stay'?'active':''}" data-action="trip-mode" data-mode="stay">Остаётся с помощником</button><button class="chip ${mode==='travel'?'active':''}" data-action="trip-mode" data-mode="travel">Едет с семьёй</button></div>${TRIP[mode].map((rows,i)=>{const count=rows.filter((_,j)=>state.trip[`${mode}-${i}-${j}`]).length;return `<section class="card phase-card"><div class="row space-between"><h3><span class="phase-num">${i+1}</span>${['До оплаты поездки','Перед отъездом и при передаче','После возвращения'][i]}</h3><span class="pill">${count} / ${rows.length}</span></div>${rows.map((r,j)=>`<label class="checklabel"><input type="checkbox" data-trip="${mode}-${i}-${j}" ${state.trip[`${mode}-${i}-${j}`]?'checked':''}><span>${r}</span></label>`).join('')}</section>`;}).join('')}<div class="note warn"><strong>Этапы не смешиваются.</strong><p>До поездки нельзя подтвердить уже состоявшееся возвращение. Отметка «сообщение отправлено» не равна принятию ухода. Ребёнок не остаётся единственным ответственным.</p></div>`;}
const PASSPORT=[['puppy','Имя щенка (необязательно)'],['clinic','Клиника и адрес'],['phone','Телефон клиники'],['backup','Запасной взрослый'],['backupphone','Телефон запасного взрослого'],['food','Точный корм'],['portion','Согласованная суточная порция с единицей измерения'],['schedule','Согласованные часы и интервалы кормления'],['vetnotes','Где лежат оригиналы назначений и документов']];
function passportView(){if(SHARED)return sharedWarning();return `<div class="note"><strong>Личная карточка — только в этом браузере.</strong><p>Она не синхронизируется с другим телефоном и не отправляется помощнику автоматически. Не храните здесь пароли, паспортные номера или адрес ребёнка. Записи о щенке не защищены отдельным паролем.</p></div><form id="passport-form" class="card"><div class="form-grid">${PASSPORT.map(([id,l])=>`<label class="field ${['schedule','vetnotes'].includes(id)?'full':''}">${l}<input name="${id}" maxlength="800" value="${esc(state.passport[id]||'')}" ${id.includes('phone')?'type="tel"':''}></label>`).join('')}<label class="field full">Заметки для передачи ухода<textarea name="notes" maxlength="4000">${esc(state.notes)}</textarea><span class="small">Перед передачей отдельно уточните фактическую последнюю еду, лекарства и туалет.</span></label></div><div class="button-row" style="margin-top:22px"><button class="button" type="submit">Сохранить карточку</button>${button('Распечатать','print')}</div></form>`;}
function logView(){if(SHARED)return sharedWarning();const sorted=state.logs.slice().sort((a,b)=>Date.parse(b.time)-Date.parse(a.time)),last=sorted[0];return `<div class="note warn"><strong>Только факты, не назначения.</strong><p>Перед едой или лекарством сверьте последнюю запись и оригинал назначения. Не повторяйте неизвестную дозу наугад. Общая галочка в «Моём дне» не заменяет этот журнал.</p></div>${last?`<div class="card" style="margin-bottom:18px"><span class="eyebrow">Последняя запись в этом браузере</span><strong>${esc(new Date(last.time).toLocaleString('ru-RU'))} · ${esc(last.who)}</strong><p style="margin-top:10px">${esc(last.what)}</p><span class="small">На другом устройстве записи могут отличаться: синхронизации нет.</span></div>`:''}<form id="log-form" class="card"><div class="form-grid"><label class="field">Что записываем<select name="kind"><option value="food">Фактическое кормление</option><option value="medicine">Лекарство по назначению врача</option><option value="care">Другая процедура или наблюдение</option></select></label><label class="field">Когда это сделали<input type="datetime-local" name="time" required value="${localDatetime()}"></label><label class="field full">Что именно сделали<textarea name="what" required maxlength="800"></textarea><span class="small">Для еды — корм и съеденное количество. Для лекарства — точное название, доза с единицей и способ из назначения. Приложение не рассчитывает дозы.</span></label><label class="field full">Кто сделал<input name="who" required maxlength="80"></label></div><button class="button" type="submit" style="margin-top:20px">Добавить фактическую запись</button></form><section class="card" style="margin-top:20px"><h3>История фактов</h3>${sorted.length?sorted.map(l=>`<div class="log-item"><div><h4>${esc(new Date(l.time).toLocaleString('ru-RU'))} · ${esc(l.who)}</h4><span class="pill">${{food:'Кормление',medicine:'Лекарство',care:'Уход / наблюдение'}[l.kind]}</span><p style="margin-top:8px">${esc(l.what)}</p></div><button class="icon-button" data-action="delete-log" data-id="${esc(l.id)}" aria-label="Удалить ошибочную запись">${icon('trash')}</button></div>`).join(''):'<p class="small">Пока записей нет. Это не означает, что щенка не кормили: сначала спросите того, кто за ним ухаживал.</p>'}</section>`;}
function mom(){return `<span class="eyebrow">Организовать · договориться · проверить</span><h1>Спокойный план для мамы</h1><p class="intro-text">Мама ведёт организацию ухода. Дочка помогает посильными делами. Присутствие папы дома не означает согласия на дежурство.</p><div class="chips adult-tabs" role="group" aria-label="Разделы мамы">${[['prepare','До покупки'],['travel','Отпуск'],['passport','Карточка щенка'],['log','Еда и лекарства'],['settings','Данные']].map(([id,name])=>`<button class="chip ${state.momTab===id?'active':''}" data-action="mom-tab" data-tab="${id}">${name}</button>`).join('')}</div>${({prepare:prepView,travel:tripView,passport:passportView,log:logView,settings:settingsBody}[state.momTab])()}`;}
function emergency(){const phone=String(state.passport.phone||'').replace(/[^+\d]/g,''),canCall=!SHARED&&/^\+?\d{6,16}$/.test(phone);return `<section class="emergency-hero"><span class="eyebrow">Всегда доступно · без игр и тестов</span><h1>Сейчас нужна помощь?</h1><p><strong>Дочке: сразу зови взрослого.</strong><br>Маме: при тяжёлом дыхании, судорогах, потере сознания, выраженной слабости с дрожью или подозрении на отравление срочно связывайтесь с клиникой.</p><div class="button-row">${canCall?`<a class="button danger" href="tel:${phone}">${icon('phone')}Позвонить в свою клинику</a>`:`<a class="button danger" href="#mom">${icon('care')}Открыть карточку мамы</a>`}<a class="button secondary" href="#article/emergency">Все тревожные признаки</a></div>${!canCall?'<p class="small" style="margin:12px 0 0">Телефон вашей клиники не заполнен. В экстренной ситуации не тратьте время на заполнение приложения.</p>':''}</section><div class="emergency-grid"><section class="emergency-step"><strong>1</strong><h3>Позвать взрослого</h3><p>Не искать ответ в игре и не пытаться лечить самостоятельно.</p></section><section class="emergency-step"><strong>2</strong><h3>Звонить и ехать</h3><p>Взрослый сообщает симптомы, возможное съеденное, время и вес, если известен.</p></section><section class="emergency-step"><strong>3</strong><h3>Не навредить</h3><p>Не давать лекарства наугад, не вызывать рвоту без указания врача, не вливать воду.</p></section></div><div class="note red"><strong>Особенно важно для маленького щенка:</strong><p>вялость, дрожь, шаткость и отказ от еды могут быть опасны. Не оставляйте проверку до следующего дня. Приложение не определяет диагноз.</p></div><div class="grid two">${featured('emergency')}${featured('firstaid')}</div><p class="small" style="margin-top:20px">Сокращённая навигационная карточка по разделам 24–25 исходного справочника; полные ограничения сохранены в статьях. <a href="#sources/24">Источники</a>.</p>`;}
function sources(){return `<span class="eyebrow">Прозрачная основа</span><h1>Откуда эти знания</h1><p class="intro-text">Основа — ваш «Щенок той-пуделя: семейный справочник», версия 1.0 от 13 октября 2026 года. Все 30 тематических разделов перенесены из DOCX. Игровые истории, интерфейс и новые изображения — дополнения для приложения, а не новые медицинские назначения.</p><div class="note"><strong>Что изменилось при переносе</strong><p>Убраны колонтитулы и печатные переходы по страницам. Добавлены поиск, отметки чтения, ссылки на темы и упражнения. Семейные 20 и 30 минут — договорённость, не научная норма ухода. Медицинские источники ниже сохранены из книги; это не сообщение о новой независимой проверке каждого сайта.</p></div><ol class="source-list">${KB.sources.map(s=>`<li id="source-${s.id}"><strong>${String(s.id).padStart(2,'0')} · ${esc(s.org)}</strong><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ${icon('arrow')}</a></li>`).join('')}</ol><section id="photos" style="scroll-margin-top:100px"><div class="section-head"><h2>Настоящие фотографии</h2></div><p class="small">Первые четыре — из книги. Ещё три добавлены для приложения. Размеры уменьшены, изображения подготовлены в WebP; исходное кадрирование из книги сохранено. Для белого пуделя Harpagornis производная фотография остаётся под CC BY-SA 4.0. Авторство не означает одобрения приложения.</p><div class="photo-grid">${KB.photos.map(p=>`<figure><button class="zoom" data-zoom="assets/${p.file}" aria-label="Увеличить фото ${p.title}"><img src="assets/${p.file}" loading="lazy" style="object-position:${p.file==='photo-white.webp'?'73% 50%':p.file==='photo-miley.webp'?'50% 20%':'center'}" alt="${p.title}"></button><figcaption><strong>${p.title}${p.new?' · добавлено':''}</strong><br>${p.author}<br><a href="${p.url}" target="_blank" rel="noopener noreferrer">Wikimedia Commons</a> · <a href="${p.licurl}" target="_blank" rel="noopener noreferrer">${p.license}</a></figcaption></figure>`).join('')}</div><div class="section-head"><h2>Иллюстрации и схемы</h2></div><div class="new-art-preview">${['play','sleep','carrier','walk'].map(n=>`<img src="assets/art-${n}.webp" alt="Новая AI-иллюстрация той-пуделя: ${n}" loading="lazy">`).join('')}</div><p class="small" style="margin-top:15px">Четыре новые иллюстрации созданы с помощью генератора изображений. Это рисунки, не фотографии реального щенка. Двадцать учебных схем и пиктограмм взяты из книги. Комната с точками и интерфейсные значки — новые схематические элементы приложения.</p></section>`;}
function settingsBody(){return `<section class="card"><h3>О данных и режиме просмотра</h3><p>«Дочке / Маме» меняет удобный вид, но не является паролем. Общей учётной записи семьи здесь нет. Прогресс и записи сохраняются в этом браузере, если его настройки это разрешают.</p><p class="small">На другом телефоне будет отдельный прогресс. Очистка данных браузера может удалить записи. Экспорт содержит ваши локальные данные: передавайте файл только нужному человеку. Никаких уведомлений, аналитики и отправки записей на сервер приложение не делает.</p>${SHARED?sharedWarning():''}<div class="settings-actions">${button(icon('download')+'Сохранить резервную копию','export')}${button('Загрузить свою копию','import')}${button('Печать текущего раздела','print')}</div><input id="import-file" type="file" accept="application/json,.json" hidden><div class="divider"></div><h3>Доступ без интернета</h3><p class="small">Нажмите кнопку при подключённом интернете. Готовность появится только после сохранения всех файлов. Ссылки на внешние источники всё равно требуют сети.</p>${button('Подготовить офлайн-доступ','offline')}<p class="status-line" id="offline-status" style="margin-top:12px"></p><div class="divider"></div><h3>Начать заново</h3><p class="small">Удаляет только данные этого приложения в этом браузере. Сначала сохраните резервную копию.</p><button class="button secondary" data-action="reset" style="color:var(--red)">Удалить мои локальные данные</button></section>`;}
function settings(){return `<span class="eyebrow">Без аккаунта и скрытой отправки данных</span><h1>Ваши данные — у вас</h1>${settingsBody()}`;}
function notFound(){return `<div class="empty"><h1>Такого раздела нет</h1><p>Откройте базу знаний или главную страницу.</p><a href="#home" class="button">На главную</a></div>`;}
function render(keepScroll=false){const y=scrollY,raw=location.hash.slice(1)||'home';[current,part='']=raw.split('/');if(current==='game'&&part==='badges'){go('badges');return;}
 layout();const f={home,day,library,badges,mom,emergency,sources,settings,play};let html=current==='article'?article(part):current==='game'?({room:roomGame,stories:storyGame,bag:bagGame,sequence:sequenceGame,myths:mythGame}[part]||notFound)():(f[current]||notFound)();$('#main').innerHTML=html;
 document.body.dataset.role=state.role;document.title=(current==='article'?(chapter(part)?.short||'База знаний'):current==='game'?'Играем и учимся':current==='emergency'?'Срочная помощь':'Лапа за лапой')+' · Щенок той-пуделя';
 if(current==='library')updateResults();if(keepScroll)scrollTo(0,y);else scrollTo(0,0);
 if(current==='sources'&&part){requestAnimationFrame(()=>{const target=part==='photos'?$('#photos'):$('#source-'+String(Number(part)));target?.scrollIntoView({block:'start'});});}
 if(!keepScroll)$('#main').focus({preventScroll:true});
}
async function offline(){const status=$('#offline-status');if(!('serviceWorker'in navigator)||!window.isSecureContext){if(status)status.textContent='Офлайн-кэш нужен HTTPS или localhost. В этой среде он недоступен.';return;}
 if(status)status.textContent='Сохраняем приложение, темы и изображения…';try{const reg=await navigator.serviceWorker.register('sw.js',{scope:'./'});await navigator.serviceWorker.ready;const w=reg.active||reg.waiting;if(!w)throw Error('Нет активного офлайн-модуля.');const channel=new MessageChannel();await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(Error('Сохранение заняло слишком много времени. Попробуйте при устойчивой сети.')),60000);channel.port1.onmessage=e=>{clearTimeout(timeout);e.data.ok?resolve():reject(Error(e.data.error||'Не удалось сохранить файлы.'));};w.postMessage({type:'CACHE_ALL'},[channel.port2]);});if($('#offline-status'))$('#offline-status').textContent='Готово: приложение и иллюстрации сохранены для этого устройства. Внешние источники доступны только с интернетом.';toast('Офлайн-файлы сохранены.');}catch(e){if($('#offline-status'))$('#offline-status').textContent='Офлайн-доступ не подготовлен: '+e.message;}}
function exportData(){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='lapaza-backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000);toast('Резервная копия содержит ваши записи. Храните её у себя.');}
function prepChanged(){if(state.decision==='go'&&!prepReady()){state.decision='none';if($('#decision'))$('#decision').value='none';}save();if($('#prep-summary'))$('#prep-summary').innerHTML=prepSummary();}
async function act(action,el){switch(action){
 case 'role':state.role=el.dataset.role==='mother'?'mother':'daughter';save();go(state.role==='mother'?'mom':'home');break;
 case 'phase':state.phase=el.dataset.phase==='home'?'home':'prepare';save();render(true);break;
 case 'favorite':{const id=el.dataset.id;if(!chapter(id))return;const found=state.favorites.includes(id);state.favorites=found?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();if(current==='library')updateResults();else render(true);toast(found?'Закладка убрана.':'Тема добавлена в закладки.');break;}
 case 'filter':filter=KB.groups.some(g=>g.id===el.dataset.filter)?el.dataset.filter:'all';render(true);break;
 case 'bookmarks':bookmarksOnly=!bookmarksOnly;render(true);break;
 case 'read':if(!state.reads.includes(el.dataset.id)&&chapter(el.dataset.id)){award(()=>state.reads.push(el.dataset.id));render(true);}else toast('Эта тема уже отмечена.');break;
 case 'task':{const block=el.dataset.block,id=el.dataset.id,v=el.dataset.status;if(!['morning','evening'].includes(block)||!/^t[1-3]$/.test(id)||!['done','help','sleep','todo'].includes(v))return;const k=state.phase+'-'+block;state.days[today()]??={};state.days[today()][k]??={};state.days[today()][k][id]=v;save();render(true);if(v==='help')toast('Скажи маме лично: приложение не отправляет сообщение.');else if(v==='sleep')toast('Отмечено как перенесённое, а не выполненное. Договорись с мамой.');break;}
 case 'hazard':{const h=G.hazards.find(x=>x.id===el.dataset.id);if(!h)return;openModal(h.name,`<div class="note" style="margin-top:0"><div class="row">${icon(h.icon,'lg')}<strong>Учебная находка</strong></div></div><p>${h.why}</p><div class="button-row"><button class="button" data-action="hazard-understood" data-id="${h.id}">Понятно</button><a class="button secondary" href="#article/${h.article}">Читать в базе</a></div>`);break;}
 case 'hazard-understood':{const id=el.dataset.id;if(G.hazards.some(h=>h.id===id)&&!state.games.room.includes(id))award(()=>state.games.room.push(id));closeModal();render(true);break;}
 case 'answer':if(quiz.selected!==null)return;quiz.selected=Number(el.dataset.answer);render(true);break;
 case 'next-story':if(quiz.selected===null)return;{const id=G.scenarios[quiz.index].id;if(!state.games.scenarios.includes(id))award(()=>state.games.scenarios.push(id));quiz.index++;quiz.selected=null;render();break;}
 case 'restart-stories':quiz={index:0,selected:null};render();break;
 case 'bag-item':{const id=el.dataset.id;if(!G.bag.some(x=>x[0]===id))return;bagSelected.has(id)?bagSelected.delete(id):bagSelected.add(id);bagResult=null;render(true);break;}
 case 'clear-bag':bagSelected.clear();bagResult=null;render(true);break;
 case 'check-bag':{const missing=G.bag.filter(x=>x[3]&&!bagSelected.has(x[0])),wrong=G.bag.filter(x=>!x[3]&&bagSelected.has(x[0]));const ok=missing.length===0&&wrong.length===0;bagResult={ok,message:ok?'Но в реальной жизни нужна ещё договорённость мамы: маршрут, подходящий уход, оплата, запасной вариант и подтверждение приёма щенка.':(missing.length?'Ещё нужны: '+missing.map(x=>x[1].toLowerCase()).join(', ')+'. ':'')+(wrong.length?'Уберите из учебной сумки: '+wrong.map(x=>x[1].toLowerCase()).join(', ')+'.':'')};if(ok&&!state.games.bag)award(()=>state.games.bag=true);render(true);break;}
 case 'order':{const i=Number(el.dataset.index),j=i+Number(el.dataset.dir);if(i<0||i>=4||j<0||j>=4)return;[order[i],order[j]]=[order[j],order[i]];orderResult=null;render(true);break;}
 case 'check-order':orderResult=order.every((v,i)=>v===i);if(orderResult&&!state.games.sequence)award(()=>state.games.sequence=true);render(true);break;
 case 'myth-answer':if(myth.selected!==null)return;myth.selected=el.dataset.value==='true';render(true);break;
 case 'next-myth':if(myth.selected===null)return;{const id=G.myths[myth.index].id;if(!state.games.myths.includes(id))award(()=>state.games.myths.push(id));myth.index++;myth.selected=null;render();break;}
 case 'restart-myths':myth={index:0,selected:null};render();break;
 case 'mom-tab':if(!['prepare','travel','passport','log','settings'].includes(el.dataset.tab))return;state.momTab=el.dataset.tab;save();render(true);break;
 case 'trip-mode':state.tripMode=el.dataset.mode==='travel'?'travel':'stay';save();render(true);break;
 case 'delete-log':if(confirm('Удалить эту ошибочную запись? Перед изменением сверьтесь с тем, кто выполнял уход.')){state.logs=state.logs.filter(x=>x.id!==el.dataset.id);save();render(true);}break;
 case 'print':window.print();break;
 case 'export':exportData();break;
 case 'import':$('#import-file')?.click();break;
 case 'reset':if(confirm('Удалить прогресс, личную карточку и журнал этого приложения на этом устройстве? Это действие нельзя отменить без резервной копии.')){state=BASE();save();quiz={index:0,selected:null};myth={index:0,selected:null};bagSelected.clear();bagResult=null;order=[2,0,3,1];orderResult=null;go('home');toast('Локальные данные приложения удалены.');}break;
 case 'offline':await offline();break;
 }}
document.addEventListener('click',e=>{const zoom=e.target.closest('[data-zoom]');if(zoom){const p=zoom.dataset.zoom;if(!/^assets\/[a-z0-9-]+\.webp$/.test(p))return;openModal('Изображение из справочника или приложения',`<div class="zoom-pane"><img class="${zoom.closest('.source-figure')?'large':''}" src="${p}" alt="Увеличенное изображение"></div><p class="small" style="margin-top:15px">Широкую схему можно прокручивать в стороны. Авторство фотографий и обозначения иллюстраций — в разделе «Источники и фотографии».</p>`);return;}const action=e.target.closest('[data-action]');if(action){e.preventDefault();Promise.resolve(act(action.dataset.action,action)).catch(err=>{console.error(err);toast('Не получилось выполнить действие. Попробуйте ещё раз.');});}if(e.target.closest('#modal a[href^="#"]'))closeModal();});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value.slice(0,150);updateResults();}if(e.target.matches('[data-proof]')&&!SHARED){const id=e.target.dataset.proof;state.checks[id]??={status:'none',proof:''};state.checks[id].proof=e.target.value.slice(0,600);prepChanged();}});
document.addEventListener('change',async e=>{const t=e.target;if(t.matches('[data-prep]')){const id=t.dataset.prep;state.checks[id]??={status:'none',proof:''};state.checks[id].status=t.value;prepChanged();}
 if(t.matches('[data-proof-tick]')){const id=t.dataset.proofTick;state.checks[id]??={status:'none',proof:''};state.checks[id].proof=t.checked?'Мама отметила: подтверждение проверено, вопросы разобраны.':'';prepChanged();}
 if(t.id==='decision'){if(t.value==='go'&&!prepReady()){t.value=state.decision;toast('Сначала разберите все пункты и добавьте записи о проверках.');return;}state.decision=t.value;prepChanged();}
 if(t.matches('[data-trip]')){state.trip[t.dataset.trip]=t.checked;save();render(true);}
 if(t.id==='import-file'&&t.files[0]){const f=t.files[0];if(f.size>1_000_000){toast('Файл слишком большой. Нужна резервная копия этого приложения.');t.value='';return;}try{const candidate=sanitize(JSON.parse(await f.text()));if(SHARED){candidate.passport={};candidate.logs=[];candidate.notes='';Object.values(candidate.checks).forEach(c=>c.proof=c.proof?'Мама отметила: подтверждение проверено, вопросы разобраны.':'');}
 if(confirm('Заменить текущие локальные данные содержимым резервной копии? Сначала сохраните старую копию, если она нужна.')){state=candidate;save();go('home');toast('Резервная копия загружена.');}}catch(err){toast('Не удалось прочитать копию: '+err.message);}t.value='';}
});
document.addEventListener('submit',e=>{if(e.target.id==='passport-form'){e.preventDefault();if(SHARED)return;const f=new FormData(e.target);for(const [id]of PASSPORT)state.passport[id]=String(f.get(id)||'').trim().slice(0,800);state.notes=String(f.get('notes')||'').trim().slice(0,4000);save();toast('Карточка сохранена только в этом браузере.');}
 if(e.target.id==='log-form'){e.preventDefault();if(SHARED)return;const f=new FormData(e.target);let date=new Date(f.get('time'));if(!Number.isFinite(date.getTime())||date.getTime()>Date.now()+60000){toast('Укажите фактическое время в прошлом или сейчас, а не будущий план.');return;}const what=String(f.get('what')||'').trim(),who=String(f.get('who')||'').trim();if(!what||!who){toast('Запишите, что сделали и кто это сделал.');return;}if(state.logs.length>=250){toast('В журнале 250 записей. Сохраните копию, затем удалите ненужные старые записи.');return;}const kind=String(f.get('kind'));if(!['food','medicine','care'].includes(kind))return;state.logs.push({id:typeof crypto.randomUUID==='function'?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2),kind,time:date.toISOString(),what:what.slice(0,800),who:who.slice(0,80)});save();render(true);toast('Фактическая запись добавлена. На другие телефоны она не отправлена.');}
});
$('#close-modal').addEventListener('click',closeModal);$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
window.addEventListener('hashchange',()=>{closeModal();render();});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{state=sanitize(JSON.parse(e.newValue));if(!$('#passport-form')&&!$('#log-form'))render(true);toast('Данные обновились в другой вкладке этого браузера.');}catch{}}});
let dateShown=today();document.addEventListener('visibilitychange',()=>{if(!document.hidden&&today()!==dateShown){dateShown=today();if(current==='day')render(true);}});
if(SHARED){state.passport={};state.logs=[];state.notes='';Object.values(state.checks).forEach(c=>c.proof=c.proof?'Мама отметила: подтверждение проверено, вопросы разобраны.':'');}
render();
// Testable pure entrypoints. No private state or hidden network calls.
window.Lapaza={sanitize,today,prepReady,version:KB.version};
})();
